function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const yes = function (x) { return s(x).toLowerCase() === 'yes'; };
function cols(node, names, label) { const h = (($(node).first().json.values || [[]])[0] || []).map(s); const C = {}; for (const n of names) { const i = h.indexOf(n); if (i < 0) { throw new Error('ABORT: ' + label + ' column missing ' + n); } C[n] = colLetter(i); } return C; }
const IC = cols('GET INV header', ['contact_person', 'sector', 'stage', 'cheque_inr_cr'], 'INVESTORS');
const PC = cols('GET PIPE header', ['pause', 'next_action', 'match_type', 'notes'], 'PIPELINE');
const EC = cols('GET ELOG header', ['resolved'], 'ERROR LOG');
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const elog = $('Read ERROR LOG').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (inv.length < 200) { throw new Error('ABORT: INVESTORS only ' + inv.length); }
if (pipe.length < 5100) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (elog.length < 2000) { throw new Error('ABORT: ERROR LOG only ' + elog.length); }
// 1. thesis corrections from the Thesis tab (correction sheet wins); values chosen so the detector reads them as equal
const EDIT = {
  blincinvest: { contact_person: 'Harsh Mehta', sector: 'Education (including HRTech), Financial Services, Healthcare & Wellness', stage: 'Pre-Series A, Series A, Series B', cheque_inr_cr: 'Cheque size min 10 Cr' },
  sianacapital: { sector: 'B2B deep-tech business models; Deeptech startups more IP Led Innovations. Heathtech, Battery Tech, Biotech Medtech' },
  dexterventures: { sector: 'Sector Agnostic' },
  araliventures: { sector: 'AI, B2B, HRTech, SaaS (no B2B marketplaces - Arali stopped that space, 11 Sep)' }
};
const idata = [], edits = [];
for (const k of Object.keys(EDIT)) { const rs = inv.filter(function (r) { return nz(r.investor) === k; });
  if (rs.length !== 1) { throw new Error('ABORT: ' + k + ' resolves to ' + rs.length + ' INVESTORS rows'); }
  for (const f of Object.keys(EDIT[k])) { if (s(rs[0][f]) === EDIT[k][f]) { continue; }
    idata.push({ range: 'INVESTORS!' + IC[f] + rs[0].row_number, values: [[EDIT[k][f]]] }); edits.push([s(rs[0].investor), f, s(rs[0][f]).slice(0, 60), EDIT[k][f]]); } }
// 2. drop AA-7 deals that fail the real-business check (keyword-only matches)
const DROPS = {
  bdevventures: { why: 'BDev backs SaaS / AI / B2B tools; this business is not one (keyword match only)', st: ['boncuisine', 'firearmor'] },
  onesixoneventures: { why: 'OneSixOne backs cloud & AI infrastructure / dual-use tech; this is an application or service business', st: ['boncuisine', 'ekosight', 'fuskiai', 'fydo', 'koncite', 'learningpad', 'mindwox', 'nexcore', 'opulytics', 'outlanders', 'pixelence', 'surechain', 'tronixai'] },
  jonathansolamon: { why: 'Jonathan backs emerging tech (EV/autonomy, digital health devices, robotics & AI, space, IoT); this is outside those areas', st: ['firearmor', 'fuskiai', 'learningpad', 'mentorcloud', 'monitorexam', 'orbitai', 'skillbytes', 'healthymaster', 'mysoul', 'nexcore', 'opulytics', 'orbislives', 'outlanders', 'sahaj'] }
};
const pdata = [], dropped = [], notFound = [];
function drop(p, why) { const rn = p.row_number; const n = s(p.notes);
  pdata.push({ range: 'PIPELINE!' + PC.pause + rn, values: [['Yes']] }, { range: 'PIPELINE!' + PC.next_action + rn, values: [['DROPPED - not per strategy']] },
    { range: 'PIPELINE!' + PC.match_type + rn, values: [['Not per strategy: ' + why]] }, { range: 'PIPELINE!' + PC.notes + rn, values: [[(n ? n + ' | ' : '') + 'DROPPED 2026-09-11 - ' + why]] });
  dropped.push([rn, s(p.deal_id), s(p.startup), s(p.investor)]); }
for (const ik of Object.keys(DROPS)) { for (const sk of DROPS[ik].st) {
  const rs = pipe.filter(function (p) { return nz(p.investor) === ik && nz(p.startup) === sk && !yes(p.deal_shared) && !yes(p.pause); });
  if (!rs.length) { notFound.push(ik + ' / ' + sk); continue; }
  if (rs.length > 1) { throw new Error('ABORT: ' + ik + ' / ' + sk + ' has ' + rs.length + ' active rows'); }
  drop(rs[0], 'real-business check - ' + DROPS[ik].why + ' (review 11 Sep)'); } }
// Chennai Angels passed on Body & Beyond; Arali stopped B2B marketplaces
for (const p of pipe) { if (yes(p.deal_shared) || yes(p.pause)) { continue; } const ik = nz(p.investor), sk = nz(p.startup);
  if (ik === 'chennaiangels' && sk === 'bodybeyond') { drop(p, 'Chennai Angels passed on Body & Beyond (too early for TCA)'); }
  if (ik === 'araliventures' && (sk === 'surechain' || sk === 'desimachines')) { drop(p, 'Arali has stopped investing in B2B marketplaces'); } }
// 3. hold Equentis until the user confirms how to apply its 8-10 Cr booked revenue / ARR bar
const held = [];
for (const p of pipe) { if (nz(p.investor) !== 'equentis' || yes(p.deal_shared) || yes(p.pause)) { continue; } const rn = p.row_number; const n = s(p.notes);
  pdata.push({ range: 'PIPELINE!' + PC.pause + rn, values: [['Yes']] }, { range: 'PIPELINE!' + PC.next_action + rn, values: [['HOLD - Equentis wants 8-10 Cr booked revenue / ARR (confirm with user)']] },
    { range: 'PIPELINE!' + PC.notes + rn, values: [[(n ? n + ' | ' : '') + 'ON HOLD 2026-09-11 - Equentis revenue bar 8-10 Cr (Thesis tab)']] });
  held.push([rn, s(p.deal_id), s(p.startup)]); }
// 4. resolve today's THESIS-WATCH flags that are handled (Equentis stays open)
const RES = ['riceberg ventures', 'blinc invest', 'siana capital', 'dexter ventures', 'thechennaiangels', 'arali ventures'];
const edata = [], resolved = [];
for (const e of elog) { if (s(e.workflow) !== 'THESIS-WATCH' || s(e.resolved) !== '') { continue; } if (RES.indexOf(s(e.investor).toLowerCase()) < 0) { continue; }
  edata.push({ range: "'ERROR LOG'!" + EC.resolved + e.row_number, values: [['Yes']] }); resolved.push([e.row_number, s(e.investor), s(e.error_type)]); }
if (dropped.length > 35) { throw new Error('ABORT: ' + dropped.length + ' drops exceeds guard'); }
if (held.length > 20) { throw new Error('ABORT: ' + held.length + ' Equentis holds exceeds guard'); }
const all = idata.concat(pdata).concat(edata);
if (!all.length) { all.push({ range: 'PIPELINE!' + PC.pause + '1', values: [['pause']] }); }
return [{ json: { pipeline_rows: pipe.length, edits: edits, dropped: dropped, not_found: notFound, equentis_held: held, resolved: resolved, data: all } }];

