const notPaused = pipe.filter(function (p) { return ids.indexOf(s(p.deal_id)) >= 0 && !yes(p.pause); }).map(function (p) { return s(p.deal_id); });
const eqActive = pipe.filter(function (p) { return nz(p.investor) === 'equentis' && !yes(p.deal_shared) && !yes(p.pause); }).length;
return [{ json: { pipeline_after: pipe.length, same_rows: pipe.length === plan.pipeline_rows, edits: plan.edits, dropped: plan.dropped.length, not_found: plan.not_found, equentis_held: plan.equentis_held.length, equentis_still_active: eqActive, resolved: plan.resolved, not_paused: notPaused,
